            if [ "$_rl_mode" = e ] && [ ! -e "$_rl_out" ]; then
                return 1
            fi
            if [ "$_rl_nl" -eq 0 ]; then printf '%s\n' "$_rl_out"; else printf '%s' "$_rl_out"; fi
        done
    }

