                for _rl_c in $_rl_path; do
                    case $_rl_c in
                        ''|.) ;;
                        ..)
                            case $_rl_out in
                                */*) _rl_out=${_rl_out%/*} ;;
                                *) _rl_out= ;;
                            esac ;;
                        *) _rl_out=$_rl_out/$_rl_c ;;
                    esac
                done
                IFS=$_rl_ifs
                [ -n "$_rl_out" ] || _rl_out=/
                if [ "$_rl_nl" -eq 0 ]; then printf '%s\n' "$_rl_out"; else printf '%s' "$_rl_out"; fi
                continue
            fi
            _rl_dir=${_rl_path%/*}
            _rl_base=${_rl_path##*/}
            _rl_old=$PWD
            if cd "$_rl_dir" 2>/dev/null; then
                _rl_dir=$(pwd -P)
                cd "$_rl_old" || :
            elif [ "$_rl_mode" = e ]; then
                return 1
            fi
