                _rl_base=${_rl_new##*/}
                _rl_n=$((_rl_n + 1))
            done
            _rl_out=$_rl_dir/$_rl_base
            if [ "$_rl_mode" = e ] && [ ! -e "$_rl_out" ]; then
                return 1
            fi
            if [ "$_rl_nl" -eq 0 ]; then printf '%s\n' "$_rl_out"; else printf '%s' "$_rl_out"; fi
        done
    }

"##);
    }
    if needs_cmp(&prog.stmts) {
        out.push_str(
            r#"
