        stmt_to_sh(st, 0, &mut body)?;
    }
    for sub in &prog.subs {
        body.push('\n');
        body.push_str(&sub.name);
        body.push_str("() {\n");
        for st in &sub.body {
            stmt_to_sh(st, 1, &mut body)?;
