//! java_backend — Java renderer (main mirror; the `backend/java` worktree
//! merges main and consumes this module).
//!
//! Consumes the ShIR (the A1 contract) in-process and emits Java source.
//! v1 subset: simple commands (Expr(Call("exec", ...)) — echo/printf
//! lowered to System.out.println/print), Assign (native String fields),
//! If/elsif/else, For, While, DoWhile, ForInit, Block (labeled — an
//! outside-loop Break targets the innermost block), Break/Continue,
//! getVar reads, bash arith (native `long` expressions via the sh2Num
//! coercion helper), `test "…"` conditions, setVar stores, and the C
//! memory arena (memAlloc/memStore/memLoad/memAdvance/memFree/memTest/
//! memElemSize — the estree ref runtime's mem* slice-2, standalone).
//! Anything outside the subset prints a marker to stderr and returns
//! Err — the corpus gate then reports FAIL on that example, and the
//! worker's pi extends the renderer (the same progression the c backend
//! followed).

use crate::ir::{ArithAst, IrExpr, IrProgram, IrStmt, IrType};

/// Renderer state: loop nesting (native break/continue are only legal
/// inside a loop) and the enclosing-block labels (an outside-loop break
/// exits the innermost A1 Block — the estree ref's sh2.break()).
#[derive(Default)]
struct JavaCtx {
    loop_depth: usize,
    block_labels: Vec<String>,
    block_seq: usize,
    /// a case clause used a glob pattern → sh2Glob helper needed
    need_glob: bool,
    /// inside a hoisted user-function body: getVar("N") reads the
    /// positional param `a[N-1]`, Return returns the value
    in_function: bool,
    /// user functions hoisted to class level (rendered before main)
    pending_fns: Vec<String>,
}

/// Render a ShIR program to Java source. `Err` on a construct outside
/// the v1 subset (the gate reports it as a FAIL).
pub fn shir_to_java(prog: &IrProgram) -> Result<String, String> {
    // builtin-op fallback arm (shir-builtin-op-20260816): the java
    // backend has NOT accepted the `builtin` op — render as exec.
    let mut prog = prog.clone();
    crate::transforms::builtin::fallback_builtin_to_exec(&mut prog);
    let mut out = String::new();
    out.push_str("public class Sh2Program {\n");
    if stmts_need_sh2num(&prog.stmts) {
        // printf %d/%i/%u conversion helper — bash coerces a
        // non-numeric arg to 0 (the java backend's fields are Strings);
        // arith reads and the mem arena coerce through it too
        out.push_str("    static long sh2Num(String s) {\n");
        out.push_str("        try { return Long.parseLong(s.trim()); } catch (Exception e) { return 0; }\n");
        out.push_str("    }\n");
    }
    if stmts_need_mem(&prog.stmts) {
        out.push_str(MEM_PREAMBLE);
    }
    if stmts_use_ext_value(&prog.stmts) {
        out.push_str(EXT_HELPERS);
    }
    if stmts_need_glob(&prog.stmts) {
        out.push_str(GLOB_HELPER);
    }
    // every assignment target / store / arith read becomes a static
    // String field (empty default — bash reads an unset var as "")
    // child-process execution layer (ported from backend/java 9f434788):
    // exported env + $? + argv/text runners. Unconditional — javac keeps
    // unused package-private statics; removes the missing-symbol class.
    out.push_str("    static java.util.LinkedHashMap<String, String> __SH_EXPORTS = new java.util.LinkedHashMap<>();\n");
    out.push_str("    static long __SH_RC = 0;\n");
    out.push_str("    static long __shRunArgv(String[] argv) {\n");
    out.push_str("        try {\n");
    out.push_str("            ProcessBuilder pb = new ProcessBuilder(argv);\n");
    out.push_str("            pb.environment().putAll(__SH_EXPORTS);\n");
    out.push_str("            pb.inheritIO();\n");
    out.push_str("            return pb.start().waitFor();\n");
    out.push_str("        } catch (Exception e) { return 127; }\n");
    out.push_str("    }\n");
    out.push_str("    static long __shRun(String cmdline) {\n");
    out.push_str("        return __shRunArgv(new String[]{\"bash\", \"-c\", cmdline});\n");
    out.push_str("    }\n");
    out.push_str("    static void __shExport(String w) {\n");
    out.push_str("        int eq = w.indexOf('=');\n");
    out.push_str("        if (eq > 0) __SH_EXPORTS.put(w.substring(0, eq), w.substring(eq + 1));\n");
    out.push_str("    }\n");
    out.push_str("    static String __shQ(String w) {\n");
    out.push_str("        return \"'\" + w.replace(\"'\", \"'\\\\''\") + \"'\";\n");
    out.push_str("    }\n");
    out.push_str("    static String __shCap(String[] argv) {\n");
    out.push_str("        try {\n");
    out.push_str("            ProcessBuilder pb = new ProcessBuilder(argv);\n");
    out.push_str("            pb.environment().putAll(__SH_EXPORTS);\n");
    out.push_str("            Process p = pb.start();\n");
    out.push_str("            byte[] b = p.getInputStream().readAllBytes();\n");
    out.push_str("            p.waitFor();\n");
    out.push_str("            __SH_RC = p.exitValue();\n");
    out.push_str("            return new String(b).trim();\n");
    out.push_str("        } catch (Exception e) { __SH_RC = 127; return \"\"; }\n");
    out.push_str("    }\n");
    let mut fields: Vec<String> = Vec::new();
    collect_vars(&prog.stmts, &mut fields);
    let has_fns = prog.stmts.iter().any(|st| {
        matches!(st, IrStmt::Function { name, .. } if name != "main")
    });
    if has_fns || prog.stmts.iter().any(|st| matches!(st, IrStmt::Function { .. })) {
        out.push_str("    static String __sh_line(String s, int n) {\n");
        out.push_str("        String[] p = s.split(\"\\\\n\");\n");
        out.push_str("        return (n >= 0 && n < p.length) ? p[n] : \"\";\n");
        out.push_str("    }\n");
    }
    if has_fns {
        out.push_str("    static String[] __sh_fArgs = new String[0];\n");
        out.push_str("    static String __sh_fArg(int n) {\n");
        out.push_str("        String[] a = __sh_fArgs;\n");
        out.push_str("        return (n >= 1 && n <= a.length) ? a[n - 1] : \"\";\n");
        out.push_str("    }\n");
        out.push_str("    static String[] __sh_setArgs(String... a) {\n");
        out.push_str("        __sh_fArgs = a;\n");
        out.push_str("        return a;\n");
        out.push_str("    }\n");
    }
    // every assignment target / store / arith read becomes a static
    // String field (empty default — bash reads an unset var as "")
    let mut fields: Vec<String> = Vec::new();
    collect_vars(&prog.stmts, &mut fields);
    for f in fields {
        if f == "?" {
            continue; // $? is the __SH_RC field, not a String var
        }
        indent(&mut out, 1);
        out.push_str(&format!("static String {f} = \"\";\n"));
    }
    out.push_str("    public static void main(String[] args) throws Exception {\n");
    // source-mapping comments: ` // line N` (the shIR convention)
    let mut ctx = JavaCtx::default();
    for (idx, st) in prog.stmts.iter().enumerate() {
        let before = out.len();
        ctx.stmt_to_java(st, 2, &mut out)?;
        let line = prog.stmt_lines.iter().find(|(i, _)| *i == idx).map(|(_, l)| *l);
        if let Some(l) = line {
            if let Some(nl) = out[before..].find('\n') {
                out.insert_str(before + nl, &format!(" // line {l}"));
            }
        }
    }
    out.push_str("    }\n");
    for f in &ctx.pending_fns {
        out.push_str(f);
    }
    out.push_str("}\n");
    Ok(out)
}

fn indent(out: &mut String, d: usize) {
    for _ in 0..d {
        out.push_str("    ");
    }
}

/// Every variable that needs a `static String` field, recursively:
/// Assign targets (any nesting), setVar store names, getVar reads, and
/// arith Var/Ident reads. A read of a never-assigned var gets the empty
/// string (bash reads unset as ""). Dedup keeps the class compileable
/// (t12_scalar_alias assigns x twice).
fn collect_vars(stmts: &[IrStmt], out: &mut Vec<String>) {
    for s in stmts {
        match s {
            IrStmt::Assign { targets, expr, .. } => {
                for t in targets {
                    push_var(&t.var, out);
                }
                collect_vars_expr(expr, out);
            }
            IrStmt::Expr(e) => collect_vars_expr(e, out),
            IrStmt::If {
                cond,
                then,
                elsifs,
                else_,
                ..
            } => {
                collect_vars_expr(cond, out);
                collect_vars(then, out);
                collect_vars(else_, out);
                for (c, b) in elsifs {
                    collect_vars_expr(c, out);
                    collect_vars(b, out);
                }
            }
            IrStmt::For { iter, body, .. } => {
                collect_vars_expr(iter, out);
                collect_vars(body, out);
            }
            IrStmt::ForInit {
                init,
                cond,
                step,
                body,
            } => {
                collect_vars(init, out);
                collect_vars_expr(cond, out);
                collect_vars(step, out);
                collect_vars(body, out);
            }
            IrStmt::While { cond, body, .. } => {
                collect_vars_expr(cond, out);
                collect_vars(body, out);
            }
            IrStmt::DoWhile { body, cond, .. } => {
                collect_vars(body, out);
                collect_vars_expr(cond, out);
            }
            IrStmt::Block(b) => collect_vars(b, out),
            IrStmt::Function { body, .. } => collect_vars(body, out),
            _ => {}
        }
    }
}

fn collect_vars_expr(e: &IrExpr, out: &mut Vec<String>) {
    match e {
        IrExpr::Call { func, args } => {
            // setVar carries the STORE name as its first Str arg;
            // getVar reads a var (a read-only var is the "" field)
            if matches!(func.as_str(), "setVar" | "getVar") {
                if let Some(IrExpr::Str(name, _)) = args.first() {
                    push_var(name, out);
                }
            }
            // bare `export NAME` reads NAME's field at runtime
            // (backend/java 9f434788)
            if func == "exec" {
                if let (Some(IrExpr::Str(c, _)), Some(IrExpr::Array(items))) =
                    (args.first(), args.get(1))
                {
                    if c == "export" {
                        for it in items {
                            if let IrExpr::Str(w, _) = it {
                                let n = w.split('=').next().unwrap_or(w);
                                if !n.is_empty() {
                                    push_var(n, out);
                                }
                            }
                        }
                    }
                }
            }
            for a in args {
                collect_vars_expr(a, out);
            }
        }
        IrExpr::Arith(a) => collect_vars_arith(a, out),
        IrExpr::Array(items) => {
            for i in items {
                collect_vars_expr(i, out);
            }
        }
        IrExpr::Var(name, _) => push_var(name, out),
        IrExpr::Ident(name) => push_var(name, out),
        IrExpr::Index { var, key } => {
            push_var(var, out);
            collect_vars_expr(key, out);
        }
        IrExpr::Ext(node) => {
            for c in node.children() {
                collect_vars_expr(c, out);
            }
        }
        _ => {}
    }
}

fn collect_vars_arith(a: &ArithAst, out: &mut Vec<String>) {
    match a {
        ArithAst::Var(name) | ArithAst::Ident(name) => push_var(name, out),
        ArithAst::Index { var, key } => {
            push_var(var, out);
            collect_vars_arith(key, out);
        }
        ArithAst::Bin { lhs, rhs, .. } => {
            collect_vars_arith(lhs, out);
            collect_vars_arith(rhs, out);
        }
        ArithAst::Un { arg, .. } => collect_vars_arith(arg, out),
        ArithAst::Cond { test, then, else_ } => {
            collect_vars_arith(test, out);
            collect_vars_arith(then, out);
            collect_vars_arith(else_, out);
        }
        ArithAst::Assign { var, rhs, .. } => {
            push_var(var, out);
            collect_vars_arith(rhs, out);
        }
        ArithAst::IncDec { var, .. } => push_var(var, out),
        ArithAst::Cast { arg, .. } => collect_vars_arith(arg, out),
        ArithAst::Num(_) | ArithAst::Sizeof(_) => {}
    }
}

/// Sanitize a shell var name to a valid Java identifier — the C
/// frontend's dotted struct names ("p.x") must read and write through
/// the SAME mangled binding.
fn java_home(name: &str) -> String {
    name.replace('.', "_").replace('-', "_")
}

fn push_var(name: &str, out: &mut Vec<String>) {
    // positional params ($1..) are NOT fields — they read __sh_fArg(N)
    if name.chars().all(|c| c.is_ascii_digit()) {
        return;
    }
    let j = java_home(name);
    if !out.iter().any(|v| *v == j) {
        out.push(j);
    }
}

fn is_plain_name(s: &str) -> bool {
    let mut cs = s.chars();
    match cs.next() {
        Some(c) if c.is_ascii_alphabetic() || c == '_' => {
            cs.all(|c| c.is_ascii_alphanumeric() || c == '_')
        }
        _ => false,
    }
}

impl JavaCtx {
    fn stmt_to_java(&mut self, st: &IrStmt, d: usize, out: &mut String) -> Result<(), String> {
        match st {
            IrStmt::Expr(e) => expr_stmt_to_java(e, d, out),
            IrStmt::Assign { targets, expr, asm, .. } => {
                // Declarator-position asm label (core request
                // c-sh-go-toplevelasmargument-20260814-042952) — no Java
                // rendering; refuse loudly (refuse > guess).
                if let Some(spec) = asm {
                    indent(out, d);
                    out.push_str(&format!(
                        "// TODO(unsupported): asm label '{}' on an assign\n",
                        spec.template
                    ));
                    return Ok(());
                }
                let t = targets.first().ok_or("assign: no target (v1)")?;
                if !t.indices.is_empty() {
                    return Err("assign with indices not in the v1 subset".into());
                }
                indent(out, d);
                out.push_str(&t.var);
                out.push_str(" = ");
                // `i++` / `i--` / `i += n` step/body arith assignments
                if let IrExpr::Arith(a) = expr {
                    match &**a {
                        ArithAst::IncDec { var, delta, .. } => {
                            let d = delta.unsigned_abs();
                            let sign = if *delta >= 0 { "+" } else { "-" };
                            out.push_str(&format!(
                                "Long.toString(sh2Num({var}) {sign} {d})"
                            ));
                            out.push_str(";\n");
                            return Ok(());
                        }
                        ArithAst::Assign { var, op, rhs } => {
                            let rhs = arith_str(rhs)?;
                            let jop = match op.as_str() {
                                "+=" => " + ",
                                "-=" => " - ",
                                "*=" => " * ",
                                "/=" => " / ",
                                "%=" => " % ",
                                _ => " + ",
                            };
                            out.push_str(&format!(
                                "Long.toString(sh2Num({var}){jop}({rhs}))"
                            ));
                            out.push_str(";\n");
                            return Ok(());
                        }
                        _ => {}
                    }
                }
                expr_to_java(expr, out)?;
                out.push_str(";\n");
                Ok(())
            }
            IrStmt::If {
                cond,
                then,
                elsifs,
                else_,
            } => {
                indent(out, d);
                out.push_str("if (");
                self.cond_to_java(cond, out)?;
                out.push_str(") {\n");
                for b in then {
                    self.stmt_to_java(b, d + 1, out)?;
                }
                for (econd, ebody) in elsifs {
                    indent(out, d);
                    out.push_str("} else if (");
                    self.cond_to_java(econd, out)?;
                    out.push_str(") {\n");
                    for b in ebody {
                        self.stmt_to_java(b, d + 1, out)?;
                    }
                }
                if !else_.is_empty() {
                    indent(out, d);
                    out.push_str("} else {\n");
                    for b in else_ {
                        self.stmt_to_java(b, d + 1, out)?;
                    }
                }
                indent(out, d);
                out.push_str("}\n");
                Ok(())
            }
            IrStmt::For { var, iter, body } => {
                indent(out, d);
                out.push_str("for (String ");
                out.push_str(var);
                out.push_str(" : new String[] {");
                for_items_to_java(iter, out)?;
                out.push_str("}) {\n");
                self.loop_depth += 1;
                for b in body {
                    self.stmt_to_java(b, d + 1, out)?;
                }
                self.loop_depth -= 1;
                indent(out, d);
                out.push_str("}\n");
                Ok(())
            }
            IrStmt::While { cond, body } => {
                indent(out, d);
                out.push_str("while (");
                self.cond_to_java(cond, out)?;
                out.push_str(") {\n");
                self.loop_depth += 1;
                for b in body {
                    self.stmt_to_java(b, d + 1, out)?;
                }
                self.loop_depth -= 1;
                indent(out, d);
                out.push_str("}\n");
                Ok(())
            }
            IrStmt::DoWhile { body, cond, until } => {
                if *until {
                    // until → while (!cond) — the body runs zero times
                    // when the cond already holds (bash until semantics)
                    indent(out, d);
                    out.push_str("while (!(");
                    self.cond_to_java(cond, out)?;
                    out.push_str(")) {\n");
                    self.loop_depth += 1;
                    for b in body {
                        self.stmt_to_java(b, d + 1, out)?;
                    }
                    self.loop_depth -= 1;
                    indent(out, d);
                    out.push_str("}\n");
                } else {
                    indent(out, d);
                    out.push_str("do {\n");
                    self.loop_depth += 1;
                    for b in body {
                        self.stmt_to_java(b, d + 1, out)?;
                    }
                    self.loop_depth -= 1;
                    indent(out, d);
                    out.push_str("} while (");
                    self.cond_to_java(cond, out)?;
                    out.push_str(");\n");
                }
                Ok(())
            }
            IrStmt::ForInit {
                init,
                cond,
                step,
                body,
            } => {
                // the A1 for-loop shape → init; while (cond) { body; step; }
                for b in init {
                    self.stmt_to_java(b, d, out)?;
                }
                indent(out, d);
                out.push_str("while (");
                self.cond_to_java(cond, out)?;
                out.push_str(") {\n");
                self.loop_depth += 1;
                for b in body {
                    self.stmt_to_java(b, d + 1, out)?;
                }
                for s in step {
                    self.stmt_to_java(s, d + 1, out)?;
                }
                self.loop_depth -= 1;
                indent(out, d);
                out.push_str("}\n");
                Ok(())
            }
            IrStmt::Block(body) => {
                // labeled block: an outside-loop Break targets the
                // innermost label (the estree ref's sh2.break() exits
                // the enclosing block — c-sh-go t36_dowhile_break's
                // do-while lowering puts the first break at block level)
                let label = format!("b{}", self.block_seq);
                self.block_seq += 1;
                self.block_labels.push(label.clone());
                indent(out, d);
                out.push_str(&format!("{label}: {{\n"));
                for b in body {
                    self.stmt_to_java(b, d + 1, out)?;
                }
                self.block_labels.pop();
                indent(out, d);
                out.push_str("}\n");
                Ok(())
            }
            IrStmt::Break => {
                if self.loop_depth > 0 {
                    indent(out, d);
                    out.push_str("break;\n");
                    Ok(())
                } else if let Some(l) = self.block_labels.last() {
                    indent(out, d);
                    out.push_str(&format!("break {l};\n"));
                    Ok(())
                } else {
                    Err("break outside a loop/block (v1)".into())
                }
            }
            IrStmt::Continue => {
                if self.loop_depth > 0 {
                    indent(out, d);
                    out.push_str("continue;\n");
                    Ok(())
                } else {
                    Err("continue outside a loop (v1)".into())
                }
            }
            IrStmt::Output {
                value,
                newline,
                target,
            } => {
                if target.is_some() {
                    return Err("Output to a filehandle target (v1)".into());
                }
                indent(out, d);
                out.push_str(if *newline { "System.out.println(" } else { "System.out.print(" });
                expr_to_java(value, out)?;
                out.push_str(");\n");
                Ok(())
            }
            IrStmt::Exit(e) => {
                let code = match e {
                    Some(x) => {
                        let mut s = String::new();
                        expr_to_java(x, &mut s)?;
                        format!("sh2Num({})", s)
                    }
                    None => "0".to_string(),
                };
                indent(out, d);
                out.push_str(&format!("System.exit((int){});\n", code));
                Ok(())
            }
            IrStmt::Return(v) => {
                indent(out, d);
                if self.in_function {
                    // user-function VALUE return (strings are the value
                    // model; numeric contexts coerce via sh2Num)
                    indent(out, d);
                    match v {
                        Some(x) => {
                            let mut r = String::new();
                            expr_to_java(x, &mut r)?;
                            out.push_str(&format!("return {r};\n"));
                        }
                        None => out.push_str("return \"\";\n"),
                    }
                    return Ok(());
                }
                match v {
                    Some(x) => {
                        out.push_str("return ");
                        expr_to_java(x, out)?;
                        out.push_str(";\n");
                    }
                    None => out.push_str("return;\n"),
                }
                Ok(())
            }
            IrStmt::SetChildError(_) => Ok(()), // status tracked elsewhere (no-op)
            IrStmt::Subshell(body) | IrStmt::Background(body) | IrStmt::Block(body) => {
                for b in body {
                    self.stmt_to_java(b, d, out)?;
                }
                Ok(())
            }
            IrStmt::Declare { vars, init, .. } => {
                for v in vars {
                    indent(out, d);
                    out.push_str(&v.name);
                    out.push_str(" = ");
                    match init {
                        Some(e) => expr_to_java(e, out)?,
                        None => out.push_str("\"\""),
                    }
                    out.push_str(";\n");
                }
                Ok(())
            }
            IrStmt::Ext(node) if node.tag() == "ForEachLine" => {
                // STREAMING line iteration (docs/shir-primitives.md
                // §ForEachLine): BufferedReader.readLine — O(1) memory,
                // never a whole-file read; readLine strips the newline.
                let fl = node.as_any().downcast_ref::<crate::shir_nodes::ForEachLine>()
                    .ok_or("tag/type")?;
                let lv = &fl.var;
                let lim_stmt = if let Some(lim) = &fl.limit {
                    // head -n K: stop after K lines (streaming early-exit)
                    let mut le = String::new();
                    expr_to_java(lim, &mut le)?;
                    format!("if (++__n >= sh2Num({le})) break;\n")
                } else {
                    String::new()
                };
                indent(out, d);
                out.push_str("{ long __n = 0; try (java.io.BufferedReader __r = new java.io.BufferedReader(new java.io.FileReader(");
                expr_to_java(&fl.source, out)?;
                out.push_str("))) {\n");
                indent(out, d + 1);
                out.push_str(&format!("String {lv};\n"));
                indent(out, d + 1);
                out.push_str(&format!("while (({lv} = __r.readLine()) != null) {{\n"));
                for b in &fl.body {
                    self.stmt_to_java(b, d + 2, out)?;
                }
                if !lim_stmt.is_empty() {
                    indent(out, d + 2);
                    out.push_str(&lim_stmt);
                }
                indent(out, d + 1);
                out.push_str("}\n");
                indent(out, d);
                out.push_str("} }\n");
                Ok(())
            }
            IrStmt::Case {
                discriminant,
                clauses,
            } => {
                let mut dstr = String::new();
                expr_to_java(discriminant, &mut dstr)?;
                let mut emitted = false;
                for cl in clauses {
                    let is_default = cl.patterns.iter().any(|p| p == "*");
                    let conds: Vec<String> = cl
                        .patterns
                        .iter()
                        .filter(|p| p.as_str() != "*")
                        .map(|p| {
                            // bash case patterns are GLOBS (* ? [...]).
                            // A literal-safe pattern stays .equals();
                            // anything with wildcards lowers to the
                            // sh2Glob regex translation.
                            let literal = !p.chars().any(|c| "*?[".contains(c));
                            if literal {
                                format!("{}.equals({})", dstr, java_str_lit(p))
                            } else if p.as_str() == "*" {
                                "true".to_string()
                            } else {
                                self.need_glob = true;
                                format!("sh2Glob({}, {})", dstr, java_str_lit(p))
                            }
                        })
                        .collect();
                    if conds.is_empty() && is_default {
                        indent(out, d);
                        out.push_str("else {\n");
                        for b in &cl.body {
                            self.stmt_to_java(b, d + 1, out)?;
                        }
                        indent(out, d);
                        out.push_str("}\n");
                        emitted = true;
                        continue;
                    }
                    indent(out, d);
                    out.push_str(if emitted { "else if (" } else { "if (" });
                    out.push_str(&conds.join(" || "));
                    out.push_str(") {\n");
                    for b in &cl.body {
                        self.stmt_to_java(b, d + 1, out)?;
                    }
                    indent(out, d);
                    out.push_str("}\n");
                    emitted = true;
                }
                Ok(())
            }
            IrStmt::Function { name, body, .. } => {
                // HOIST to class level: a `static` method nested inside
                // main is invalid Java. The fn takes its POSITIONAL
                // params as `String[] a` (the body's getVar("N") reads —
                // the $1 convention) and returns the value string.
                let id = java_ident(name);
                let prev = self.in_function;
                self.in_function = true;
                let mut saved = std::mem::take(out);
                let mut fntext = String::new();
                fntext.push_str(&format!(
                    "{ind}static String {id}(String[] a) throws Exception {{\n",
                    ind = "    ".repeat(d)
                ));
                for b in body {
                    self.stmt_to_java(b, d + 1, &mut fntext)?;
                }
                if !body_has_return(body) {
                    // a void-ish fn still needs a value-return (call sites
                    // read __SH_RET / discard)
                    fntext.push_str(&format!(
                        "{ind}return \"\";\n",
                        ind = "    ".repeat(d + 1)
                    ));
                }
                fntext.push_str(&format!("{}}}
", "    ".repeat(d)));
                self.pending_fns.push(fntext);
                self.in_function = prev;
                *out = saved;
                Ok(())
            }
            IrStmt::Redirect { inner, redirects } => {
                // render the inner commands; apply a simple fd-1 write
                // redirect (`> file` / `>> file`) by wrapping the output
                // in a print-to-file (capture-free approximation for the
                // v1 subset).
                let write_target: Option<(String, bool)> = redirects.iter().find_map(|r| {
                    if r.fd.unwrap_or(1) == 1 && (r.mode == "w" || r.mode == "a") {
                        let mut p = String::new();
                        if expr_to_java(&r.target, &mut p).is_ok() {
                            Some((p, r.mode == "a"))
                        } else {
                            None
                        }
                    } else {
                        None
                    }
                });
                for b in inner {
                    self.stmt_to_java(b, d, out)?;
                }
                if let Some((path, append)) = write_target {
                    indent(out, d);
                    let opt = if append {
                        "java.nio.file.StandardOpenOption.APPEND"
                    } else {
                        "java.nio.file.StandardOpenOption.TRUNCATE_EXISTING, java.nio.file.StandardOpenOption.CREATE"
                    };
                    out.push_str(&format!(
                        "java.nio.file.Files.write(java.nio.file.Paths.get({path}), \"\".getBytes(), {opt});\n"
                    ));
                }
                Ok(())
            }
            IrStmt::Pipeline { stages, .. } => {
                // idiom lift: `echo ARG | grep -q [-v] P` → native
                // substring check (no process spawn)
                if let Some(rc) = grep_q_lift_java(stages)? {
                    indent(out, d);
                    out.push_str(&rc);
                    out.push('\n');
                    return Ok(());
                }
                for st in stages {
                    for b in st {
                        self.stmt_to_java(b, d, out)?;
                    }
                }
                Ok(())
            }
            IrStmt::WriteFile {
                path,
                content,
                append,
            } => {
                let mut p = String::new();
                expr_to_java(path, &mut p)?;
                let mut c = String::new();
                expr_to_java(content, &mut c)?;
                indent(out, d);
                let opt = if *append {
                    "java.nio.file.StandardOpenOption.APPEND"
                } else {
                    "java.nio.file.StandardOpenOption.TRUNCATE_EXISTING, java.nio.file.StandardOpenOption.CREATE"
                };
                out.push_str(&format!(
                    "java.nio.file.Files.write(java.nio.file.Paths.get({p}), ({c}).getBytes(), {opt});\n"
                ));
                Ok(())
            }
            IrStmt::DeclareArray { var, elements, .. } => {
                let mut elems = String::new();
                for (i, e) in elements.iter().enumerate() {
                    if i > 0 {
                        elems.push_str(", ");
                    }
                    expr_to_java(e, &mut elems)?;
                }
                indent(out, d);
                out.push_str(&format!(
                    "{var} = java.util.Arrays.toString(new String[]{{{elems}}});\n"
                ));
                Ok(())
            }
            other => Err(format!("statement not in the v1 subset: {other:?}")),
        }
    }

    /// A condition: `expr != null` for exec calls (v1 — a command that
    /// succeeded), a var read, or a `test "…"` string (the mini
    /// evaluator; an unparsed shape keeps the v1 `true` fallback).
    fn cond_to_java(&self, cond: &IrExpr, out: &mut String) -> Result<(), String> {
        match cond {
            IrExpr::Var(name, _) => {
                // a bare variable condition (the goto restructure's flag
                // guards): truthiness of the string home — nonempty=true
                out.push_str(&format!("(!({name} == null || {name}.isEmpty()))"));
                Ok(())
            }
            IrExpr::Call { func, .. } if func == "getVar" => {
                expr_to_java(cond, out)?;
                out.push_str(" != null");
                Ok(())
            }
            IrExpr::Call { func, args, .. } if func == "test" => {
                if let Some(IrExpr::Str(s, _)) = args.first() {
                    if let Some(c) = test_render(s) {
                        out.push_str(&c);
                        return Ok(());
                    }
                }
                out.push_str("true");
                Ok(())
            }
            // testArith(Str) — the C frontend's arithmetic-truth condition
            // (`(($i % 2) == 0)`, `($x & 1)`): parse and render via the
            // Arith AST (a literal `true` made every such cond vacuous)
            IrExpr::Call { func, args, .. }
                if func == "testArith" || func == "arith" =>
            {
                // the C frontend's arithmetic-truth condition
                // (`(($i % 2) == 0)`, `($x & 1)`): parse and render via
                // the Arith AST (a literal `true` made every such cond
                // vacuous)
                if let Some(IrExpr::Str(s2, _)) = args.first() {
                    let norm = norm_arith_text(s2);
                    if let Some(ast) = crate::shir::parse_arith(norm.trim()) {
                        let mut r = String::new();
                        arith_to_java(&ast, &mut r)?;
                        // condition context: nonzero = true
                        out.push_str(&format!("(({}) != 0)", r));
                        return Ok(());
                    }
                }
                out.push_str("false");
                Ok(())
            }
            IrExpr::Call { func, args, .. } if func == "contains" => {
                // `echo X | grep LIT >/dev/null` → contains(X, LIT): native
                // String.contains (java fields are Strings).
                if let (Some(needle), Some(pattern)) = (args.first(), args.get(1)) {
                    let mut n = String::new();
                    expr_to_java(needle, &mut n)?;
                    let mut p = String::new();
                    expr_to_java(pattern, &mut p)?;
                    out.push_str(&format!("({n}).contains({p})"));
                    return Ok(());
                }
                Ok(())
            }
            IrExpr::Call { func, args, .. } if func == "exec" => {
                // `true`/`false` builtins used as a condition
                if let Some(IrExpr::Str(cmd, _)) = args.first() {
                    match cmd.as_str() {
                        "true" => {
                            out.push_str("true");
                            return Ok(());
                        }
                        "false" => {
                            out.push_str("false");
                            return Ok(());
                        }
                        _ => {}
                    }
                }
                out.push_str("true");
                Ok(())
            }
            IrExpr::BinOp { lhs, op, rhs } => {
                let jop = match op {
                    crate::ir::BinOpKind::And => " && ",
                    crate::ir::BinOpKind::Or => " || ",
                    crate::ir::BinOpKind::Eq => " == ",
                    crate::ir::BinOpKind::Ne => " != ",
                    crate::ir::BinOpKind::Not => {
                        let mut inner = String::new();
                        self.cond_to_java(rhs, &mut inner)?;
                        out.push_str(&format!("!({inner})"));
                        return Ok(());
                    }
                    _ => return Err(format!("condition op not in the v1 Java subset: {op:?}")),
                };
                let mut l = String::new();
                let mut r = String::new();
                self.cond_to_java(lhs, &mut l)?;
                self.cond_to_java(rhs, &mut r)?;
                out.push_str(&format!("({l}){jop}({r})"));
                Ok(())
            }
            IrExpr::Ext(node) => {
                // StringContains renders raw (a boolean condition); other
                // value primitives in condition position are truthy strings
                // (non-empty = true) — render and test non-empty.
                let n = node.as_ref();
                if n.tag() == "StringContains" {
                    let s = ext_value_to_java(n, false)?;
                    out.push_str(&s);
                } else {
                    out.push_str("true");
                }
                Ok(())
            }
            IrExpr::Call { .. } => {
                out.push_str("true");
                Ok(())
            }
            other => Err(format!("condition not in the v1 Java subset: {other:?}")),
        }
    }
}

fn expr_stmt_to_java(e: &IrExpr, d: usize, out: &mut String) -> Result<(), String> {
    match e {
        // setVar(cap, capture(Arrow[fnCall(f, args)])) — the C frontend's
        // outparam channel: the callee echoes its out-param values; the
        // caller captures STDOUT into the var (System.out redirection)
        IrExpr::Call { func, args, .. } if func == "setVar" => {
            if let (Some(IrExpr::Str(name, _)), Some(val)) = (args.first(), args.get(1)) {
                if let IrExpr::Call { func: cf, args: cargs, .. } = val {
                    if cf == "capture" {
                        if let Some(IrExpr::Arrow(body)) = cargs.first() {
                            let mut call_src = String::new();
                            let mut captured = false;
                            for st in body.iter() {
                                if let IrStmt::Expr(IrExpr::Call { func: f2, args: a2, .. }) = st {
                                    if f2 == "fnCall" || f2 == "fnValue" {
                                        if let Some(IrExpr::Str(fname, _)) = a2.first() {
                                            let mut vals: Vec<String> = Vec::new();
                                            if let Some(IrExpr::Array(items)) = a2.get(1) {
                                                for w in items {
                                                    vals.push(word_to_java(w)?);
                                                }
                                            }
                                            call_src = format!(
                                                "{}(__sh_setArgs(new String[]{{{}}}))",
                                                java_ident(fname),
                                                vals.join(", ")
                                            );
                                            captured = true;
                                        }
                                    }
                                }
                            }
                            if captured {
                                indent(out, d);
                                out.push_str("java.io.PrintStream __old = System.out;\n");
                                indent(out, d);
                                out.push_str("java.io.ByteArrayOutputStream __b = new java.io.ByteArrayOutputStream();\n");
                                indent(out, d);
                                out.push_str("System.setOut(new java.io.PrintStream(__b));\n");
                                indent(out, d);
                                out.push_str(&call_src);
                                if !call_src.ends_with(';') {
                                    out.push(';');
                                }
                                out.push('\n');
                                indent(out, d);
                                out.push_str("System.setOut(__old);\n");
                                indent(out, d);
                                out.push_str(&format!(
                                    "{} = __b.toString();\n",
                                    java_home(name)
                                ));
                                return Ok(());
                            }
                        }
                    }
                }
            // a PLAIN setVar: typed assignment to the sanitized home
            if let (Some(IrExpr::Str(name, _)), Some(val)) = (args.first(), args.get(1)) {
                let v = word_to_java(val)?;
                indent(out, d);
                out.push_str(&format!("{} = {};\n", java_home(name), v));
                return Ok(());
            }
            }

            // a bare `[ cond ]` / arith-truth statement: emit the
            // a bare `[ cond ]` / arith-truth statement: emit the
            // condition truth — ONLY for actual condition calls (a
            // setVar's NAME argument must never render as a -n test of
            // itself)
            if matches!(
                func.as_str(),
                "test" | "testArith" | "arith"
            ) {
                if let Some(IrExpr::Str(s2, _)) = args.first() {
                    let norm = norm_arith_text(s2);
                    let c = match crate::shir::parse_arith(norm.trim()) {
                        Some(ast) => {
                            let mut r = String::new();
                            arith_to_java(&ast, &mut r)?;
                            format!("(({}) != 0)", r)
                        }
                        None => test_render(s2).unwrap_or_else(|| "true".to_string()),
                    };
                    use std::sync::atomic::{AtomicUsize, Ordering};
                    static TSEQ: AtomicUsize = AtomicUsize::new(0);
                    let seq = TSEQ.fetch_add(1, Ordering::Relaxed) + 1;
                    indent(out, d);
                    out.push_str(&format!("boolean __t{seq} = {c};\n"));
                    return Ok(());
                }
            }
            Ok(())
        }
        IrExpr::Call { func, args, .. } if func == "exec" => {
            let cmd = match args.first() {
                Some(IrExpr::Str(name, _)) => name.clone(),
                _ => return Err("exec with non-literal command not in the v1 subset".into()),
            };
            match cmd.as_str() {
                "echo" => {
                    let words = &args[1..];
                    let mut parts = Vec::new();
                    for w in words {
                        parts.push(word_to_java(w)?);
                    }
                    indent(out, d);
                    out.push_str("System.out.println(");
                    out.push_str(&parts.join(" + "));
                    out.push_str(");\n");
                }
                "printf" => {
                    // The A1 shape: exec("printf", [Array[fmt, arg...]]).
                    // Apply the %s/%d/%i/%u conversions over a literal
                    // format (cpp-sh-go t32_varargs.cc — the folded
                    // `sum(3,1,2,3)` → "6" must land through %d, not be
                    // joined as a word); mirrors the estree ref / js
                    // renderer's printf lowering. A flags/width/prec
                    // spec keeps the raw join (the v1 fallback).
                    let Some(IrExpr::Array(items)) = args.get(1) else {
                        return Err("printf without an args array (v1)".into());
                    };
                    let fmt = match items.first() {
                        Some(IrExpr::Str(s, _)) => s.clone(),
                        Some(IrExpr::Interpolate(parts)) => {
                            // an f-string format whose parts are all literal
                            let mut t = String::new();
                            let mut ok = true;
                            for p in parts {
                                match p {
                                    crate::ir::InterpPart::Lit(s) => t.push_str(s),
                                    _ => {
                                        ok = false;
                                        break;
                                    }
                                }
                            }
                            if ok {
                                t
                            } else {
                                return Err("printf with a non-literal format (v1)".into());
                            }
                        }
                        _ => return Err("printf with a non-literal format (v1)".into()),
                    };
                    let parsed = printf_parse(&fmt);
                    let Some((els, n_specs)) = parsed else {
                        // complex spec — the v1 raw join
                        indent(out, d);
                        out.push_str("System.out.print(");
                        let mut parts = Vec::new();
                        for w in &args[1..] {
                            parts.push(word_to_java(w)?);
                        }
                        out.push_str(&parts.join(" + "));
                        out.push_str(");\n");
                        return Ok(());
                    };
                    let fmt_args: Vec<&IrExpr> = items[1..].iter().collect();
                    let arg_exprs: Result<Vec<String>, String> =
                        fmt_args.iter().map(|a| word_to_java(a)).collect();
                    let arg_exprs = arg_exprs?;
                    let mut pieces: Vec<String> = Vec::new();
                    if n_specs == 0 {
                        // printf(1): the format text repeats once per arg
                        let text = java_str_lit(&printf_unescape(&fmt));
                        let passes = if fmt_args.is_empty() { 1 } else { fmt_args.len() };
                        for _ in 0..passes {
                            pieces.push(text.clone());
                        }
                    } else {
                        let passes = if arg_exprs.is_empty() {
                            1
                        } else {
                            (arg_exprs.len() + n_specs - 1) / n_specs
                        };
                        let mut ai = 0usize;
                        for _pass in 0..passes {
                            for (text, spec) in &els {
                                if let Some((conv, fw)) = spec {
                                    let arg = arg_exprs
                                        .get(ai)
                                        .cloned()
                                        .unwrap_or_else(|| "\"\"".into());
                                    ai += 1;
                                    // flags/width via String.format (the
                                    // java runtime owns padding); bare
                                    // specs keep the cheap direct renders
                                    match (conv, fw.as_str()) {
                                        ('s', "") => pieces.push(arg),
                                        ('s', w) => pieces.push(format!(
                                            "String.format(\"%{w}s\", {arg})"
                                        )),
                                        (_, "") => pieces.push(format!(
                                            "Long.toString(sh2Num({arg}))"
                                        )),
                                        (_, w) => pieces.push(format!(
                                            "String.format(\"%{w}d\", sh2Num({arg}))"
                                        )),
                                    }
                                } else {
                                    pieces.push(java_str_lit(&printf_unescape(text)));
                                }
                            }
                        }
                    }
                    indent(out, d);
                    out.push_str("System.out.print(");
                    out.push_str(&pieces.join(" + "));
                    out.push_str(");\n");
                }
                "export" => {
                    // export VAR=value / bare export NAME — record in
                    // __SH_EXPORTS so every child process sees it
                    // (backend/java 9f434788)
                    if let Some(IrExpr::Array(items)) = args.get(1) {
                        for it in items {
                            match it {
                                IrExpr::Str(w, _) if !w.contains('$') && w.contains('=') => {
                                    let (n, v) = w.split_once('=').unwrap();
                                    indent(out, d);
                                    out.push_str(&format!(
                                        "__SH_EXPORTS.put({}, {});\n",
                                        java_str_lit(n),
                                        java_str_lit(v)
                                    ));
                                }
                                IrExpr::Str(n, _) => {
                                    // bare NAME: mark the CURRENT field value
                                    indent(out, d);
                                    out.push_str(&format!(
                                        "__SH_EXPORTS.put({}, {});\n",
                                        java_str_lit(n),
                                        java_home(n)
                                    ));
                                }
                                _ => {
                                    let wj = word_to_java(it)?;
                                    indent(out, d);
                                    out.push_str(&format!("__shExport({wj});\n"));
                                }
                            }
                        }
                    }
                }
                other => {
                    // any other command: a REAL child process — argv exec,
                    // stdout/stderr inherited, exit status lands in $?
                    // (__SH_RC). Replaces the v1 comment stub.
                    let mut parts = vec![java_str_lit(other)];
                    if let Some(IrExpr::Array(items)) = args.get(1) {
                        for it in items {
                            parts.push(word_to_java(it)?);
                        }
                    }
                    indent(out, d);
                    out.push_str(&format!(
                        "__SH_RC = __shRunArgv(new String[]{{{}}});\n",
                        parts.join(", ")
                    ));
                }
            }
            Ok(())
        }
        IrExpr::Call { func, args, .. } if func == "getVar" => {
            let name = match args.first() {
                Some(IrExpr::Str(n, _)) => n.clone(),
                _ => return Err("getVar with non-literal name (v1)".into()),
            };
            indent(out, d);
            if name == "?" {
                out.push_str("System.out.println(__SH_RC);\n");
                return Ok(());
            }
            out.push_str(&format!("System.out.println({name});\n"));
            Ok(())
        }
        IrExpr::Call { func, args, .. } if func == "setVar" => {
            // the A1's store write: setVar("name", value) → the
            // assignment (c-sh-go t19_malloc's arena pointer)
            let name = match args.first() {
                Some(IrExpr::Str(n, _)) => n.clone(),
                _ => return Err("setVar with non-literal name (v1)".into()),
            };
            let val = args.get(1).ok_or("setVar without a value (v1)")?;
            indent(out, d);
            out.push_str(&format!("{} = ", java_home(&name)));
            out.push_str(&word_to_java(val)?);
            out.push_str(";\n");
            Ok(())
        }
        IrExpr::Call { func, .. } if func == "break" || func == "continue" => {
            indent(out, d);
            out.push_str(func);
            out.push_str(";\n");
            Ok(())
        }
        IrExpr::Call { func, args, .. } if is_mem_func(func) => {
            indent(out, d);
            out.push_str(&mem_call_java(func, args)?);
            out.push_str(";\n");
            Ok(())
        }
        IrExpr::BinOp { lhs, rhs, op } => {
            // statement-position command chain (`a && b`, `a || b`) —
            // passthrough as ONE bash -c text (bash owns precedence and
            // short-circuit), stdout inherited, rc lands in $?
            // (backend/java 9f434788)
            if !matches!(*op, crate::ir::BinOpKind::And | crate::ir::BinOpKind::Or) {
                return Err(format!("statement chain op not in the v1 Java subset: {op:?}"));
            }
            // idiom lift: `test -f X && cat X` → native guarded read (no
            // process spawn)
            if matches!(*op, crate::ir::BinOpKind::And) {
                if let Some((path, catpath)) = guarded_cat_java(lhs, rhs)? {
                    indent(out, d);
                    out.push_str(&format!(
                        "if (java.nio.file.Files.isRegularFile(java.nio.file.Paths.get({path}))) {{\n"
                    ));
                    indent(out, d + 1);
                    out.push_str(&format!(
                        "System.out.print(new String(java.nio.file.Files.readAllBytes(java.nio.file.Paths.get({catpath}))));\n"
                    ));
                    indent(out, d + 1);
                    out.push_str("__SH_RC = 0;\n");
                    indent(out, d);
                    out.push_str("} else {\n");
                    indent(out, d + 1);
                    out.push_str("__SH_RC = 1;\n");
                    indent(out, d);
                    out.push_str("}\n");
                    return Ok(());
                }
            }
            // side_text returns a JAVA EXPRESSION evaluating to the
            // shell-quoted command text (__shQ single-quotes at RUNTIME,
            // so interpolated args are safe)
            fn side_text(e: &IrExpr) -> Result<String, String> {
                match e {
                    IrExpr::BinOp { lhs, rhs, op } => {
                        let sep = match *op {
                            crate::ir::BinOpKind::And => " && ",
                            crate::ir::BinOpKind::Or => " || ",
                            _ => return Err("chain op".into()),
                        };
                        Ok(format!(
                            "({}) + \"{}\" + ({})",
                            side_text(lhs)?,
                            sep,
                            side_text(rhs)?
                        ))
                    }
                    IrExpr::Call { func, args, .. }
                        if matches!(func.as_str(), "exec" | "builtin") =>
                    {
                        let mut words: Vec<String> = Vec::new();
                        for a in args {
                            match a {
                                IrExpr::Str(w, _) => words.push(format!("__shQ({})", java_str_lit(w))),
                                IrExpr::Array(items) => {
                                    for it in items {
                                        words.push(format!("__shQ({})", word_to_java(it)?));
                                    }
                                }
                                other => return Err(format!("chain word {other:?} not in the v1 subset")),
                            }
                        }
                        Ok(words.join(" + \" \" + "))
                    }
                    other => Err(format!("chain operand {other:?} not in the v1 subset")),
                }
            }
            let t = side_text(e)?;
            indent(out, d);
            out.push_str(&format!("__SH_RC = __shRun({});\n", t));
            Ok(())
        }
        IrExpr::Arith(a) => {
            // `((i++))` — the side-effect statement form (c-sh-go
            // t28_dowhile / t44_nested_loops: IncDec in an Expr stmt);
            // any other arith computes and discards (bash `((expr))`)
            if let ArithAst::IncDec { var, delta, .. } = &**a {
                indent(out, d);
                out.push_str(&format!(
                    "{var} = Long.toString(sh2Num({var}) + ({delta}));\n"
                ));
                return Ok(());
            }
            indent(out, d);
            out.push_str("Long.toString(");
            arith_to_java(a, out)?;
            out.push_str(");\n");
            Ok(())
        }
        other => Err(format!("expression not in the v1 Java subset: {other:?}")),
    }
}

/// A java string literal: escape backslash, quote, and control chars
/// (a raw newline inside the literal is a compile error — cpp-sh-go
/// t30_static_assert.cc's `printf "static assert ok\n"` carries a real
/// \n in the A1 Str).
/// Sanitize a shell function name into a Java identifier.
fn java_ident(name: &str) -> String {
    let mut out = String::with_capacity(name.len());
    for (i, c) in name.chars().enumerate() {
        if c.is_ascii_alphanumeric() || c == '_' {
            out.push(c);
        } else if i > 0 {
            out.push('_');
        }
    }
    if out.is_empty() {
        "f".to_string()
    } else {
        out
    }
}

/// Does a function body contain a `Return(Some(..))`? If so the Java
/// method needs a non-void return type.
fn body_has_return(body: &[IrStmt]) -> bool {
    body.iter().any(|s| matches!(s, IrStmt::Return(Some(_))))
}

fn java_str_lit(s: &str) -> String {
    let mut out = String::with_capacity(s.len() + 2);
    out.push('"');
    for c in s.chars() {
        match c {
            '\\' => out.push_str("\\\\"),
            '"' => out.push_str("\\\""),
            '\n' => out.push_str("\\n"),
            '\t' => out.push_str("\\t"),
            '\r' => out.push_str("\\r"),
            '\u{8}' => out.push_str("\\b"),
            '\u{c}' => out.push_str("\\f"),
            c if (c as u32) < 0x20 => out.push_str(&format!("\\u{:04x}", c as u32)),
            c => out.push(c),
        }
    }
    out.push('"');
    out
}

/// printf(1) format parse (mirror of the js renderer's printf_parse):
/// %s/%d/%i/%u conversions over literal text runs. A flags/width/prec
/// spec (or any other conversion) yields None — the caller keeps the
/// v1 raw join. `%%` is an escaped percent.
///
/// Flags+width (%-10s, %05d — backend/java 9f434788) ARE parsed: the
/// spec carries the flags/width text and the renderer applies it via
/// String.format. Precision still yields None.
fn printf_parse(fmt: &str) -> Option<(Vec<(String, Option<(char, String)>)>, usize)> {
    let chars: Vec<char> = fmt.chars().collect();
    let mut els: Vec<(String, Option<(char, String)>)> = Vec::new();
    let mut text = String::new();
    let mut n_specs = 0usize;
    let mut pos = 0usize;
    while pos < chars.len() {
        if chars[pos] == '%' {
            let mut i = pos + 1;
            let flags_start = i;
            while i < chars.len() && matches!(chars[i], '-' | '+' | ' ' | '0' | '#') {
                i += 1;
            }
            let has_flags = i > flags_start;
            let mut has_width = false;
            while i < chars.len() && chars[i].is_ascii_digit() {
                has_width = true;
                i += 1;
            }
            let mut has_prec = false;
            if i < chars.len() && chars[i] == '.' {
                i += 1;
                has_prec = true;
                while i < chars.len() && chars[i].is_ascii_digit() {
                    i += 1;
                }
            }
            let Some(&conv) = chars.get(i) else {
                return None;
            };
            if has_prec {
                return None;
            }
            // [-0-9]* flags+width carried on the spec ('' when bare)
            let fw: String = chars[flags_start..i].iter().collect();
            match conv {
                's' | 'd' | 'i' | 'u' => {
                    if !text.is_empty() {
                        els.push((std::mem::take(&mut text), None));
                    }
                    els.push((String::new(), Some((conv, fw))));
                    n_specs += 1;
                    pos = i + 1;
                }
                '%' => {
                    text.push('%');
                    pos = i + 1;
                }
                _ => return None,
            }
        } else {
            text.push(chars[pos]);
            pos += 1;
        }
    }
    if !text.is_empty() {
        els.push((text, None));
    }
    Some((els, n_specs))
}

/// printf(1) backslash escapes in the format text (\n, \t, \r, \a,
/// \b, \f, \v, \\\\, octal) — mirror of the js renderer's
/// printf_unescape; the A1 Str values carry the raw escape sequences.
fn printf_unescape(s: &str) -> String {
    let mut out = s.to_string();
    for (from, to) in [
        ("\\n", "\n"),
        ("\\t", "\t"),
        ("\\r", "\r"),
        ("\\a", "\x07"),
        ("\\b", "\x08"),
        ("\\f", "\x0c"),
        ("\\v", "\x0b"),
        ("\\\\", "\\"),
    ] {
        out = out.replace(from, to);
    }
    let chars: Vec<char> = out.chars().collect();
    let mut res = String::with_capacity(out.len());
    let mut i = 0;
    while i < chars.len() {
        if chars[i] == '\\' && i + 1 < chars.len() {
            let mut oct = String::new();
            let mut j = i + 1;
            while j < chars.len() && oct.len() < 3 && matches!(chars[j], '0'..='7') {
                oct.push(chars[j]);
                j += 1;
            }
            if !oct.is_empty() {
                if let Ok(v) = u32::from_str_radix(&oct, 8) {
                    if let Some(c) = char::from_u32(v) {
                        res.push(c);
                        i = j;
                        continue;
                    }
                }
            }
        }
        res.push(chars[i]);
        i += 1;
    }
    res
}

/// Does any statement need the sh2Num coercion helper? A printf with a
/// numeric conversion (%d/%i/%u), an arith expression (Var/Ident reads
/// coerce through it), or a mem* call (the arena parses through it).
fn stmts_need_sh2num(stmts: &[IrStmt]) -> bool {
    stmts.iter().any(|st| match st {
        IrStmt::Expr(e) => expr_need_sh2num(e),
        IrStmt::Assign { expr, .. } => expr_need_sh2num(expr),
        IrStmt::If {
            cond,
            then,
            elsifs,
            else_,
            ..
        } => {
            expr_need_sh2num(cond)
                || stmts_need_sh2num(then)
                || stmts_need_sh2num(else_)
                || elsifs.iter().any(|(c, b)| expr_need_sh2num(c) || stmts_need_sh2num(b))
        }
        IrStmt::For { iter, body, .. } => expr_need_sh2num(iter) || stmts_need_sh2num(body),
        IrStmt::ForInit {
            init,
            cond,
            step,
            body,
        } => {
            stmts_need_sh2num(init)
                || expr_need_sh2num(cond)
                || stmts_need_sh2num(step)
                || stmts_need_sh2num(body)
        }
        IrStmt::While { cond, body, .. } => expr_need_sh2num(cond) || stmts_need_sh2num(body),
        IrStmt::DoWhile { body, cond, .. } => stmts_need_sh2num(body) || expr_need_sh2num(cond),
        IrStmt::Block(b) => stmts_need_sh2num(b),
        // text-ops ForEachLine bodies carry sh2Num arithmetic
        IrStmt::Ext(node) => node.children().iter().any(|c| match c {
            IrStmt::Expr(e) => expr_need_sh2num(e),
            IrStmt::Assign { expr, .. } => expr_need_sh2num(expr),
            IrStmt::If { cond, then, elsifs, else_ } => {
                expr_need_sh2num(cond)
                    || stmts_need_sh2num(then)
                    || stmts_need_sh2num(else_)
                    || elsifs.iter().any(|(cc, b)| expr_need_sh2num(cc) || stmts_need_sh2num(b))
            }
            IrStmt::While { cond, body, .. } | IrStmt::DoWhile { body, cond, .. } => {
                expr_need_sh2num(cond) || stmts_need_sh2num(body)
            }
            IrStmt::Output { value, .. } => expr_need_sh2num(value),
            _ => false,
        }),
        _ => false,
    })
}

fn expr_need_sh2num(e: &IrExpr) -> bool {
    match e {
        IrExpr::Call { func, args } if func == "exec" => {
            // printf with a literal format containing a numeric conv
            if let Some(IrExpr::Array(items)) = args.get(1) {
                if let Some(IrExpr::Str(fmt, _)) = items.first() {
                    if printf_parse(fmt)
                        .map(|(els, _)| {
                            els.iter()
                                .any(|(_, spec)| matches!(spec, Some(('d' | 'i' | 'u', _))))
                        })
                        .unwrap_or(false)
                    {
                        return true;
                    }
                }
            }
            // echo/interpolated words may carry arith (sh2Num reads)
            args.iter().any(expr_need_sh2num)
        }
        IrExpr::Arith(_) => true,
        IrExpr::Call { func, .. } if func == "test" => true,
        IrExpr::Call { func, .. } if is_mem_func(func) => true,
        // text-ops numeric string arithmetic renders through sh2Num
        IrExpr::BinOp { .. } => true,
        IrExpr::Array(items) => items.iter().any(expr_need_sh2num),
        _ => false,
    }
}

/// Does any statement contain a mem* call? Those need the arena
/// preamble emitted.
fn stmts_need_mem(stmts: &[IrStmt]) -> bool {
    stmts.iter().any(|st| match st {
        IrStmt::Expr(e) => expr_need_mem(e),
        IrStmt::Assign { expr, .. } => expr_need_mem(expr),
        IrStmt::If {
            cond,
            then,
            elsifs,
            else_,
            ..
        } => {
            expr_need_mem(cond)
                || stmts_need_mem(then)
                || stmts_need_mem(else_)
                || elsifs.iter().any(|(c, b)| expr_need_mem(c) || stmts_need_mem(b))
        }
        IrStmt::For { iter, body, .. } => expr_need_mem(iter) || stmts_need_mem(body),
        IrStmt::ForInit {
            init,
            cond,
            step,
            body,
        } => {
            stmts_need_mem(init)
                || expr_need_mem(cond)
                || stmts_need_mem(step)
                || stmts_need_mem(body)
        }
        IrStmt::While { cond, body, .. } => expr_need_mem(cond) || stmts_need_mem(body),
        IrStmt::DoWhile { body, cond, .. } => stmts_need_mem(body) || expr_need_mem(cond),
        IrStmt::Block(b) => stmts_need_mem(b),
        _ => false,
    })
}

fn expr_need_mem(e: &IrExpr) -> bool {
    match e {
        IrExpr::Call { func, .. } if is_mem_func(func) => true,
        IrExpr::Call { args, .. } => args.iter().any(expr_need_mem),
        IrExpr::Array(items) => items.iter().any(expr_need_mem),
        IrExpr::Arith(a) => arith_need_mem(a),
        _ => false,
    }
}

fn arith_need_mem(a: &ArithAst) -> bool {
    match a {
        ArithAst::Bin { lhs, rhs, .. } => arith_need_mem(lhs) || arith_need_mem(rhs),
        ArithAst::Un { arg, .. } => arith_need_mem(arg),
        ArithAst::Cond { test, then, else_ } => {
            arith_need_mem(test) || arith_need_mem(then) || arith_need_mem(else_)
        }
        ArithAst::Assign { rhs, .. } => arith_need_mem(rhs),
        ArithAst::Cast { arg, .. } => arith_need_mem(arg),
        ArithAst::Index { key, .. } => arith_need_mem(key),
        _ => false,
    }
}

/// `$(seq …)` / `$(wc -l FILE)` — native Java idiom lifts (no process
/// spawn). Returns the Java expression, or None if the capture isn't one
/// of these idioms.
fn capture_idiom_java(args: &[IrExpr]) -> Result<Option<String>, String> {
    let cmd = match args.first() {
        Some(IrExpr::Str(c, _)) => c.as_str(),
        _ => return Ok(None),
    };
    let items = match args.get(1) {
        Some(IrExpr::Array(it)) => it,
        _ => return Ok(None),
    };
    let str_of = |e: &IrExpr| match e {
        IrExpr::Str(s, _) => Some(s.clone()),
        _ => None,
    };
    match cmd {
        "seq" => {
            let nums: Vec<i64> = items
                .iter()
                .filter_map(str_of)
                .filter_map(|s| s.trim().parse().ok())
                .collect();
            if nums.is_empty() || nums.len() != items.len() {
                return Ok(None);
            }
            let (start, inc, end) = match nums.as_slice() {
                [end] => (1, 1, *end),
                [start, end] => (*start, 1, *end),
                [start, inc, end] => (*start, *inc, *end),
                _ => return Ok(None),
            };
            if inc == 0 {
                return Ok(None);
            }
            let mut vals = Vec::new();
            if inc > 0 {
                let mut v = start;
                while v <= end {
                    vals.push(v);
                    v += inc;
                }
            } else {
                let mut v = start;
                while v >= end {
                    vals.push(v);
                    v += inc;
                }
            }
            let arr = vals
                .iter()
                .map(|v| java_str_lit(&v.to_string()))
                .collect::<Vec<_>>()
                .join(", ");
            Ok(Some(format!(
                "String.join(\"\\n\", new String[]{{{arr}}})"
            )))
        }
        "wc" => {
            if items.len() == 2 && str_of(&items[0]).as_deref() == Some("-l") {
                let file = match str_of(&items[1]) {
                    Some(f) => f,
                    None => return Ok(None),
                };
                Ok(Some(format!(
                    "String.valueOf(java.nio.file.Files.readAllLines(java.nio.file.Paths.get({})).size())",
                    java_str_lit(&file)
                )))
            } else {
                Ok(None)
            }
        }
        _ => Ok(None),
    }
}

/// `test -f X && cat X` → the (path, catpath) Java expressions for a
/// native guarded read (no process spawn).
fn guarded_cat_java(lhs: &IrExpr, rhs: &IrExpr) -> Result<Option<(String, String)>, String> {
    let (largs, rargs) = match (lhs, rhs) {
        (IrExpr::Call { func: lf, args: la }, IrExpr::Call { func: rf, args: ra })
            if lf == "exec" && rf == "exec" => (la, ra),
        _ => return Ok(None),
    };
    let lname = match largs.first() {
        Some(IrExpr::Str(n, _)) => n.as_str(),
        _ => return Ok(None),
    };
    let rname = match rargs.first() {
        Some(IrExpr::Str(n, _)) => n.as_str(),
        _ => return Ok(None),
    };
    if lname != "test" || rname != "cat" {
        return Ok(None);
    }
    let litems = match largs.get(1) {
        Some(IrExpr::Array(it)) => it,
        _ => return Ok(None),
    };
    let ritems = match rargs.get(1) {
        Some(IrExpr::Array(it)) => it,
        _ => return Ok(None),
    };
    if litems.len() != 2 || ritems.len() != 1 {
        return Ok(None);
    }
    let flag = match &litems[0] {
        IrExpr::Str(s, _) => s.as_str(),
        _ => return Ok(None),
    };
    if flag != "-f" {
        return Ok(None);
    }
    let path = word_to_java(&litems[1])?;
    let catpath = word_to_java(&ritems[0])?;
    Ok(Some((path, catpath)))
}

/// `echo ARG | grep -q [-v] P` → `__SH_RC = (ARG.contains("P") ? 0 : 1)`
/// (native substring check, no process spawn).
fn grep_q_lift_java(stages: &[Vec<IrStmt>]) -> Result<Option<String>, String> {
    if stages.len() != 2 {
        return Ok(None);
    }
    let echo_arg = match stages[0].as_slice() {
        [IrStmt::Expr(IrExpr::Call { func, args })] if func == "builtin" || func == "exec" => {
            let name = match args.first() {
                Some(IrExpr::Str(n, _)) => n.as_str(),
                _ => return Ok(None),
            };
            if name != "echo" {
                return Ok(None);
            }
            let items = match args.get(1) {
                Some(IrExpr::Array(it)) => it,
                _ => return Ok(None),
            };
            if items.len() != 1 {
                return Ok(None);
            }
            word_to_java(&items[0])?
        }
        _ => return Ok(None),
    };
    let (pat, invert) = match stages[1].as_slice() {
        [IrStmt::Expr(IrExpr::Call { func, args })] if func == "builtin" || func == "exec" => {
            let name = match args.first() {
                Some(IrExpr::Str(n, _)) => n.as_str(),
                _ => return Ok(None),
            };
            if name != "grep" {
                return Ok(None);
            }
            let items = match args.get(1) {
                Some(IrExpr::Array(it)) => it,
                _ => return Ok(None),
            };
            let mut pat: Option<String> = None;
            let mut invert = false;
            for it in items {
                match it {
                    IrExpr::Str(s, _) if s == "-q" => {}
                    IrExpr::Str(s, _) if s == "-v" => invert = true,
                    IrExpr::Str(s, _) => pat = Some(s.clone()),
                    _ => return Ok(None),
                }
            }
            (pat, invert)
        }
        _ => return Ok(None),
    };
    let (Some(pat), invert) = (pat, invert) else {
        return Ok(None);
    };
    let neg = if invert { "!" } else { "" };
    Ok(Some(format!(
        "__SH_RC = ({neg}({echo_arg}).contains({}) ? 0 : 1);",
        java_str_lit(&pat)
    )))
}

fn word_to_java(e: &IrExpr) -> Result<String, String> {
    match e {
        // ternary(cond, a, b) — the C frontend's conditional: the cond is
        // a test/testArith STRING, branches are lowered values
        IrExpr::Ternary { cond, then, else_ } => {
            let mut cc = String::new();
            match cond.as_ref() {
                IrExpr::Call { func, args, .. }
                    if func == "test" || func == "testArith" || func == "arith" =>
                {
                    if let Some(IrExpr::Str(sv, _)) = args.first() {
                        let norm = norm_arith_text(sv);
                        match crate::shir::parse_arith(norm.trim()) {
                            Some(ast) => {
                                arith_to_java(&ast, &mut cc)?;
                                cc = format!("(({}) != 0)", cc);
                            }
                            None => match test_render(sv) {
                                Some(t) => cc.push_str(&t),
                                None => cc.push_str("true"),
                            },
                        }
                    }
                }
                other => expr_to_java(other, &mut cc)?,
            }
            let bt = word_to_java(then)?;
            let bf = word_to_java(else_)?;
            return Ok(format!("({cc} ? {bt} : {bf})"));
        }
        // fnValue(name, [args]) — a user-function VALUE call: set the
        // positional-args channel then invoke (the fn reads $1.. via
        // __sh_fArg)
        IrExpr::Call { func, args, .. } if func == "fnValue" => {
            if let (Some(IrExpr::Str(name, _)), Some(IrExpr::Array(items))) =
                (args.first(), args.get(1))
            {
                let vals: Vec<String> = items.iter().map(|w| word_to_java(w)).collect::<Result<_, _>>()?;
                return Ok(format!(
                    "{name}(__sh_setArgs(new String[]{{{vals}}}))",
                    vals = vals.join(", ")
                ));
            }
            Err("fnValue with unsupported shape".into())
        }
        // a DIRECT user-function call in word position — the parameter-
        // expansion lowering emits `param(op, name, a, b, value)` calls
        // (the `${s##*/}`-style ops) as words; set the positional-args
        // channel then invoke, exactly like fnValue
        IrExpr::Call { func, args, .. } if func == "param" => {
            let vals: Vec<String> = args.iter().map(|w| word_to_java(w)).collect::<Result<_, _>>()?;
            Ok(format!(
                "param(__sh_setArgs(new String[]{{{vals}}}))",
                vals = vals.join(", ")
            ))
        }
        // join(words...) — a single value is itself; multiple words join
        // with spaces (the parameter-expansion lowering wraps a lone
        // `param(...)` value in join)
        IrExpr::Call { func, args, .. } if func == "join" => {
            if args.len() == 1 {
                return word_to_java(&args[0]);
            }
            let parts: Vec<String> = args.iter().map(|w| word_to_java(w)).collect::<Result<_, _>>()?;
            Ok(format!("\"\" + {}", parts.join(" + \" \" + ")))
        }
        // listVar("@") — `"$@"`: all positional params joined with spaces
        IrExpr::Call { func, args, .. } if func == "listVar" => {
            if let Some(IrExpr::Str(name, _)) = args.first() {
                if name == "@" {
                    return Ok("String.join(\" \", __sh_fArgs)".into());
                }
            }
            Err("listVar with unsupported shape".into())
        }
        IrExpr::Str(s, _) => Ok(java_str_lit(s)),
        // an INT literal in word position is the STRING model (the
        // value flows as text; %d prints identically)
        IrExpr::Int(i) => Ok(java_str_lit(&i.to_string())),
        IrExpr::Call { func, args, .. } if func == "getVar" => {
            if let Some(IrExpr::Str(name, _)) = args.first() {
                if name == "?" {
                    return Ok("Long.toString(__SH_RC)".into());
                }
                // a DIGIT name is the positional param ($1 convention):
                // inside hoisted functions this reads __sh_fArg(N)
                if let Ok(k) = name.parse::<usize>() {
                    if (1..=9).contains(&k) {
                        return Ok(format!("__sh_fArg({k})"));
                    }
                }
                let j = java_home(name);
                return Ok(format!("({j} == null ? \"\" : {j})"));
            }
            Err("getVar with non-literal name (v1)".into())
        }
        IrExpr::Var(name, _) => {
            let j = java_home(name);
            Ok(format!("({j} == null ? \"\" : {j})"))
        }
        IrExpr::Arith(a) => Ok(format!("Long.toString({})", arith_str(a)?)),
        IrExpr::Call { func, args, .. } if is_mem_func(func) => mem_call_java(func, args),
        IrExpr::Call { func, args, .. } if func == "split" => {
            // word splitting of a single value: just the value
            match args.first() {
                Some(inner) => word_to_java(inner),
                None => Err("split with no arg (v1)".into()),
            }
        }
        IrExpr::Capture { expr, .. } => {
            // `$(cmd args)` in a word — run and capture stdout
            if let IrExpr::Arrow(body) = expr.as_ref() {
                if let [IrStmt::Expr(e)] = body.as_slice() {
                    if let IrExpr::Call { func: f, args } = e {
                        if f == "exec" {
                            // idiom lifts: `$(seq …)` / `$(wc -l FILE)` —
                            // native, no process spawn
                            if let Some(lift) = capture_idiom_java(args)? {
                                return Ok(lift);
                            }
                            let mut argv = Vec::new();
                            if let Some(IrExpr::Str(c, _)) = args.first() {
                                argv.push(java_str_lit(c));
                            }
                            if let Some(IrExpr::Array(items)) = args.get(1) {
                                for it in items {
                                    argv.push(word_to_java(it)?);
                                }
                            }
                            return Ok(format!(
                                "__shCap(new String[]{{{}}})",
                                argv.join(", ")
                            ));
                        }
                    }
                }
            }
            Err("capture not in the v1 Java subset".into())
        }
        IrExpr::Array(items) => {
            let parts: Result<Vec<String>, String> =
                items.iter().map(word_to_java).collect();
            Ok(format!("(\"\" + {})", parts?.join(" + \" \" + ")))
        }
        IrExpr::Interpolate(parts) => {
            // `"hello"` / `"hi $name"` — concatenate lit + expr parts
            let mut out = String::from("\"\" + ");
            let mut lit = String::new();
            for p in parts {
                match p {
                    crate::ir::InterpPart::Lit(s) => lit.push_str(s),
                    crate::ir::InterpPart::Expr(x) => {
                        if !lit.is_empty() {
                            out.push_str(&java_str_lit(&lit));
                            out.push_str(" + ");
                            lit.clear();
                        }
                        out.push_str(&word_to_java(x)?);
                        out.push_str(" + ");
                    }
                }
            }
            if !lit.is_empty() || out == "\"\" + " {
                out.push_str(&java_str_lit(&lit));
            } else {
                out.truncate(out.len() - 3);
            }
            Ok(out)
        }
        other => Err(format!("word not in the v1 Java subset: {other:?}")),
    }
}

/// Max positional param index (`getVar("N")`) read anywhere in `body`.
/// Normalize an arith STRING for parse_arith (`$x`/`${x}` → bare idents).
fn norm_arith_text(s: &str) -> String {
    let norm: String = s
        .chars()
        .enumerate()
        .map(|(i, c)| {
            if c == '$'
                && i + 1 < s.len()
                && (s[i + 1..].starts_with('{')
                    || s[i + 1..]
                        .chars()
                        .next()
                        .map_or(false, |n| n.is_ascii_alphabetic() || n == '_'))
            {
                ' '
            } else {
                c
            }
        })
        .collect();
    norm.replace('{', " ").replace('}', " ")
}

fn collect_max_param(stmts: &[IrStmt], max: &mut usize) {
    fn scan_expr(e: &IrExpr, max: &mut usize) {
        if let IrExpr::Call { func, args, .. } = e {
            if func == "getVar" {
                if let Some(IrExpr::Str(n, _)) = args.first() {
                    if let Ok(k) = n.parse::<usize>() {
                        if k > *max {
                            *max = k;
                        }
                    }
                }
            }
            for a in args {
                scan_expr(a, max);
            }
        } else if let IrExpr::Arith(a) = e {
            scan_arith_param(a, max);
        }
    }
    fn scan_arith_param(a: &ArithAst, max: &mut usize) {
        match a {
            ArithAst::Var(name) | ArithAst::Ident(name) => {
                if let Ok(k) = name.parse::<usize>() {
                    if k > *max {
                        *max = k;
                    }
                }
            }
            ArithAst::Bin { lhs, rhs, .. } => {
                scan_arith_param(lhs, max);
                scan_arith_param(rhs, max);
            }
            _ => {}
        }
    }
    fn scan_stmt(st: &IrStmt, max: &mut usize) {
        match st {
            IrStmt::Assign { targets: _, expr, .. } => scan_expr(expr, max),
            IrStmt::Expr(e) => scan_expr(e, max),
            IrStmt::Return(Some(e)) => scan_expr(e, max),
            IrStmt::If { cond, then, elsifs, else_, .. } => {
                scan_expr(cond, max);
                for b in then {
                    scan_stmt(b, max);
                }
                for (_, b) in elsifs {
                    for x in b {
                        scan_stmt(x, max);
                    }
                }
                for b in else_ {
                    scan_stmt(b, max);
                }
            }
            IrStmt::While { cond, body, .. } | IrStmt::DoWhile { cond, body, .. } => {
                scan_expr(cond, max);
                for b in body {
                    scan_stmt(b, max);
                }
            }
            IrStmt::Block(body) | IrStmt::Function { body, .. } => {
                for b in body {
                    scan_stmt(b, max);
                }
            }
            _ => {}
        }
    }
    // walk: find every getVar("N") in the body
    fn go(st: &IrStmt, max: &mut usize) {
        scan_stmt(st, max);
    }
    let _ = go;
}


fn expr_to_java(e: &IrExpr, out: &mut String) -> Result<(), String> {
    match e {
        IrExpr::Str(s, _) => {
            out.push_str(&java_str_lit(s));
            Ok(())
        }
        IrExpr::Call { func, args, .. } if func == "getVar" => {
            if let Some(IrExpr::Str(name, _)) = args.first() {
                // a DIGIT name is the positional param ($1 convention):
                // inside hoisted user functions this reads __sh_fArg(N)
                if let Ok(k) = name.parse::<usize>() {
                    if (1..=9).contains(&k) {
                        out.push_str(&format!("__sh_fArg({k})"));
                        return Ok(());
                    }
                }
                out.push_str(name);
                return Ok(());
            }
            Err("getVar with non-literal name (v1)".into())
        }
        IrExpr::Call { func, args, .. } if func == "line" => {
            // multi-return line read (`line(cap, N)`): the Nth newline-
            // split field of the captured output
            if let (Some(v), Some(IrExpr::Str(i, _))) = (args.first(), args.get(1)) {
                let ve = word_to_java(v)?;
                let n: usize = i.parse().unwrap_or(0);
                out.push_str(&format!("__sh_line({ve}, {n})"));
                return Ok(());
            }
            Err("line with unsupported shape".into())
        }
        IrExpr::Call { func, args, .. } if func == "setArray" => {
            // `declare -a arr=(a b c)` — render as a bracketed array string
            let mut parts = String::new();
            if let Some(IrExpr::Array(items)) = args.get(1) {
                for (i, it) in items.iter().enumerate() {
                    if i > 0 {
                        parts.push_str(", ");
                    }
                    parts.push_str(&word_to_java(it)?);
                }
            }
            out.push_str(&format!("(\"[\" + {})", if parts.is_empty() { "\"\"".to_string() } else { format!("java.util.Arrays.toString(new String[]{{{parts}}})") }));
            Ok(())
        }
        IrExpr::Var(name, _) => {
            out.push_str(name);
            Ok(())
        }
        IrExpr::Arith(a) => {
            out.push_str(&format!("Long.toString({})", arith_str(a)?));
            Ok(())
        }
        IrExpr::Call { func, args, .. } if is_mem_func(func) => {
            out.push_str(&mem_call_java(func, args)?);
            Ok(())
        }
        IrExpr::Capture { expr, .. } => {
            // `$(cmd args)` — run and capture stdout via ProcessBuilder
            if let IrExpr::Arrow(body) = expr.as_ref() {
                if let [IrStmt::Expr(e)] = body.as_slice() {
                    if let IrExpr::Call { func: f, args } = e {
                        if f == "exec" {
                            // idiom lifts: `$(seq …)` / `$(wc -l FILE)` —
                            // native, no process spawn
                            if let Some(lift) = capture_idiom_java(args)? {
                                out.push_str(&lift);
                                return Ok(());
                            }
                            let mut argv = Vec::new();
                            if let Some(IrExpr::Str(c, _)) = args.first() {
                                argv.push(java_str_lit(c));
                            }
                            if let Some(IrExpr::Array(items)) = args.get(1) {
                                for it in items {
                                    argv.push(word_to_java(it)?);
                                }
                            }
                            out.push_str(&format!(
                                "__shCap(new String[]{{{}}})",
                                argv.join(", ")
                            ));
                            return Ok(());
                        }
                    }
                }
            }
            Err("capture not in the v1 Java subset".into())
        }
        IrExpr::Int(v) => {
            out.push_str(&java_str_lit(&v.to_string()));
            Ok(())
        }
        IrExpr::BinOp { lhs, op, rhs } => {
            // numeric string arithmetic: bash vars are strings, so render
            // through sh2Num coercion then back to a string
            let jop = match op {
                crate::ir::BinOpKind::Add => "+",
                crate::ir::BinOpKind::Sub => "-",
                crate::ir::BinOpKind::Mul => "*",
                crate::ir::BinOpKind::Div => "/",
                _ => return Err(format!("BinOp not in the Java value subset: {op:?}")),
            };
            let mut l = String::new();
            expr_to_java(lhs, &mut l)?;
            let mut r = String::new();
            expr_to_java(rhs, &mut r)?;
            out.push_str(&format!(
                "String.valueOf(sh2Num({l}) {jop} sh2Num({r}))",
                l = l, r = r, jop = jop
            ));
            Ok(())
        }
        IrExpr::Ext(node) => {
            let s = ext_value_to_java(node.as_ref(), true)?;
            out.push_str(&s);
            Ok(())
        }
        IrExpr::Call { func, args, .. } if func == "test" => {
            if let Some(IrExpr::Str(s2, _)) = args.first() {
                if let Some(c) = test_render(s2) {
                    out.push_str(&c);
                    return Ok(());
                }
            }
            out.push_str("true");
            Ok(())
        }
        // testArith(Str) — the C frontend's arithmetic-truth condition
        IrExpr::Call { func, args, .. } if func == "testArith" => {
            if let Some(IrExpr::Str(s2, _)) = args.first() {
                let norm: String = s2
                    .chars()
                    .enumerate()
                    .map(|(i, c)| {
                        if c == '$'
                            && i + 1 < s2.len()
                            && (s2[i + 1..].starts_with('{')
                                || s2[i + 1..]
                                    .chars()
                                    .next()
                                    .map_or(false, |n| n.is_ascii_alphabetic() || n == '_'))
                        {
                            ' '
                        } else {
                            c
                        }
                    })
                    .collect();
                let norm = norm.replace('{', " ").replace('}', " ");
                if let Some(ast) = crate::shir::parse_arith(norm.trim()) {
                    arith_to_java(&ast, out)?;
                    return Ok(());
                }
            }
            out.push_str("false");
            Ok(())
        }
        IrExpr::Call { func, args, .. } if func == "ternary" => {
            // cond ? a : b — the cond is a test/testArith STRING; the
            // branches are lowered values. Render as the java conditional.
            if let [c0, b0v, b1v] = args.as_slice() {
                let mut cc = String::new();
                match c0 {
                    IrExpr::Str(sv, _) => {
                        let norm: String = sv
                            .chars()
                            .enumerate()
                            .map(|(i, ch)| {
                                if ch == '$'
                                    && i + 1 < sv.len()
                                    && (sv[i + 1..].starts_with('{')
                                        || sv[i + 1..]
                                            .chars()
                                            .next()
                                            .map_or(false, |n| {
                                                n.is_ascii_alphabetic() || n == '_'
                                            }))
                                {
                                    ' '
                                } else {
                                    ch
                                }
                            })
                            .collect();
                        let norm = norm.replace('{', " ").replace('}', " ");
                        match crate::shir::parse_arith(norm.trim()) {
                            Some(ast) => arith_to_java(&ast, &mut cc)?,
                            None => match test_render(sv) {
                                Some(t) => cc.push_str(&t),
                                None => cc.push_str("true"),
                            },
                        }
                    }
                    other => expr_to_java(other, &mut cc)?,
                }
                let mut bt = String::new();
                expr_to_java(b0v, &mut bt)?;
                let mut bf = String::new();
                expr_to_java(b1v, &mut bf)?;
                out.push_str(&format!("({cc} ? {bt} : {bf})"));
                return Ok(());
            }
            Err("ternary with unsupported shape".into())
        }
        // ternary(cond, a, b) — the C frontend's conditional: the cond is
        // a test/testArith STRING, the branches are lowered values
        IrExpr::Ternary { cond, then, else_ } => {
            let mut cc = String::new();
            match cond.as_ref() {
                IrExpr::Call { func, args, .. }
                    if func == "test" || func == "testArith" || func == "arith" =>
                {
                    if let Some(IrExpr::Str(sv, _)) = args.first() {
                        let norm = norm_arith_text(sv);
                        match crate::shir::parse_arith(norm.trim()) {
                            Some(ast) => {
                                arith_to_java(&ast, &mut cc)?;
                                cc = format!("(({}) != 0)", cc);
